package com.toa.gear;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
final class ApplicantGearOverlay extends Overlay
{
    private final Client client;
    private final ToaApplicantGearConfig config;
    private final ApplicantInterface applicants;
    private final GearPanel panel;
    private String hoveredName;
    private volatile Rectangle popupBounds;
    private Rectangle bridge;

    @Inject
    ApplicantGearOverlay(Client client, ToaApplicantGearConfig config,
        ApplicantInterface applicants, GearPanel panel)
    {
        this.client = client;
        this.config = config;
        this.applicants = applicants;
        this.panel = panel;
        setPosition(OverlayPosition.DYNAMIC);
        // Widget callbacks are conditional on native interface drawing. The final buffer pass
        // runs each rendered frame, after native redraws, in both software and GPU clients.
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Rectangle header = applicants.header();
        if (header == null || client.isMenuOpen())
        {
            clearHover();
            return null;
        }
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setColor(GearPanel.GOLD);
            int hx = header.x + header.width / 2;
            int hy = header.y + header.height / 2;
            g.drawPolygon(new int[]{hx - 5, hx + 5, hx + 5, hx, hx - 5},
                new int[]{hy - 5, hy - 5, hy + 2, hy + 6, hy + 2}, 5);
            g.drawLine(hx, hy - 3, hx, hy + 3);
            net.runelite.api.Point point = client.getMouseCanvasPosition();
            java.awt.Point mouse = new java.awt.Point(point.getX(), point.getY());
            ApplicantRow selected = null;
            // Keep the card open while hovering its items; discard it if that applicant disappears.
            if (hoveredName != null && ((popupBounds != null && popupBounds.contains(mouse))
                || (bridge != null && bridge.contains(mouse))))
            {
                for (ApplicantRow row : applicants.rows())
                {
                    if (Names.key(row.name).equals(hoveredName))
                    {
                        selected = row;
                        break;
                    }
                }
            }
            for (ApplicantRow row : applicants.rows())
            {
                boolean rowHovered = row.gearBounds.contains(mouse)
                    || (config.hoverName() && row.nameBounds.contains(mouse));
                // The existing popup is on top of underlying applicant rows.
                if (selected == null && rowHovered)
                {
                    selected = row;
                }
                Rectangle b = row.gearBounds;
                g.setColor(rowHovered ? new Color(119, 94, 48, 170) : new Color(0, 0, 0, 65));
                g.fillRect(b.x + 2, b.y + 2, Math.max(0, b.width - 4), Math.max(0, b.height - 4));
                int x = b.x + b.width / 2;
                int y = b.y + b.height / 2;
                Graphics2D icon = (Graphics2D) g.create();
                try
                {
                    icon.clip(b);
                    icon.setColor(row.gear.available() ? new Color(169, 207, 128) : GearPanel.MUTED);
                    icon.drawOval(x - 6, y - 6, 8, 8);
                    icon.drawLine(x + 1, y + 1, x + 6, y + 6);
                }
                finally
                {
                    icon.dispose();
                }
            }
            if (selected == null)
            {
                clearHover();
                return null;
            }
            hoveredName = Names.key(selected.name);
            Rectangle bounds = GearPanel.place(selected.gearBounds,
                new Dimension(client.getCanvasWidth(), client.getCanvasHeight()));
            popupBounds = bounds;
            bridge = bridge(selected.gearBounds, bounds);
            panel.render(g, bounds, selected, mouse);
            return null;
        }
        finally
        {
            g.dispose();
        }
    }

    static Rectangle bridge(Rectangle anchor, Rectangle popup)
    {
        int left = Math.min(anchor.x + anchor.width, popup.x + popup.width);
        int right = Math.max(anchor.x, popup.x);
        int top = Math.max(anchor.y, popup.y);
        int bottom = Math.min(anchor.y + anchor.height, popup.y + popup.height);
        return new Rectangle(left, top, Math.max(0, right - left), Math.max(0, bottom - top));
    }

    boolean blocks(java.awt.Point point)
    {
        Rectangle bounds = popupBounds;
        return bounds != null && bounds.contains(point);
    }

    void clearHover()
    {
        hoveredName = null;
        popupBounds = null;
        bridge = null;
    }
}

package com.toa.gear;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

/** Client-thread adapter for the native interface; never changes actions, text or sorting. */
@Singleton
final class ApplicantInterface
{
    static final int COLUMN_WIDTH = 26;
    // Native scripts: init clears rows; 6729 finishes sorting and reveals the selected tab.
    static final int INIT_SCRIPT = 6615;
    static final int COMPLETE_SCRIPT = 6729;
    static final int AUTO_REFRESH_SCRIPT = 6748;
    static final int AUTO_REFRESH_INTERVAL = 500;
    static final int MAX_REFRESH_CYCLES = 50;
    // Both native tables place names at +1, but have different row layouts.
    private enum Table
    {
        APPLICANTS(InterfaceID.ToaPartydetails.APPLICANTS, InterfaceID.ToaPartydetails.APPLICANTS_NAME,
            InterfaceID.ToaPartydetails.APPLICANTS_LIST, InterfaceID.ToaPartydetails.APPLICANTS_LIST_CONTAINER, 20),
        MEMBERS(InterfaceID.ToaPartydetails.MEMBERS, InterfaceID.ToaPartydetails.MEMBERS_NAME,
            InterfaceID.ToaPartydetails.MEMBERS_LIST, InterfaceID.ToaPartydetails.MEMBERS_LIST_CONTAINER, 13);

        final int panel;
        final int nameHeader;
        final int list;
        final int container;
        final int stride;

        Table(int panel, int nameHeader, int list, int container, int stride)
        {
            this.panel = panel;
            this.nameHeader = nameHeader;
            this.list = list;
            this.container = container;
            this.stride = stride;
        }
    }
    private final Client client;
    private final Map<Widget, Integer> originalWidths = new IdentityHashMap<>();
    private List<ApplicantRow> rows = Collections.emptyList();
    private Rectangle header;
    private Widget refreshRoot;
    private Rectangle refreshRootBounds;
    private int refreshStartCycle;
    private boolean rebuilding;
    private Table lastTable;
    private int reloadCycle = -1;

    @Inject
    ApplicantInterface(Client client)
    {
        this.client = client;
    }

    void update()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            clear();
            return;
        }
        if (refreshRoot != null && !validRefreshContext())
        {
            cancelAutomaticRefresh();
        }
        if (rebuilding)
        {
            // Retain only row identity/geometry during this explicit native transaction.
            // Equipment remains live, including becoming unavailable when a player leaves range.
            updateGearOnly();
            return;
        }
        Table table = null;
        for (Table candidate : Table.values())
        {
            if (visible(client.getWidget(candidate.panel)))
            {
                table = candidate;
                break;
            }
        }
        if (table == null)
        {
            clear();
            return;
        }
        if (header != null && table == lastTable && reloadCycle == client.getGameCycle())
        {
            // Same-group reloads reset cached widget positions during this cycle.
            // At high FPS several frames can render before the next layout cycle.
            prepareNameWidths(table);
            updateGearOnly();
            return;
        }
        reloadCycle = -1;
        Widget tablePanel = client.getWidget(table.panel);
        Widget nameHeader = client.getWidget(table.nameHeader);
        Widget list = client.getWidget(table.list);
        Widget container = client.getWidget(table.container);
        if (!visible(nameHeader) || !visible(list) || !visible(container))
        {
            clear();
            return;
        }

        Rectangle nameColumn = nameHeader.getBounds();
        if (nameColumn.width < 100 || nameColumn.height <= 0)
        {
            clear();
            return;
        }
        Rectangle clip = container.getBounds().intersection(tablePanel.getBounds());
        header = new Rectangle(nameColumn.x + nameColumn.width - COLUMN_WIDTH,
            nameColumn.y, COLUMN_WIDTH, nameColumn.height);
        Widget[] children = list.getChildren();
        List<ApplicantRow> next = new ArrayList<>();
        Set<Widget> active = Collections.newSetFromMap(new IdentityHashMap<>());
        Map<String, Player> nearby = nearbyPlayers();
        if (children != null)
        {
            for (int i = 1; i < children.length; i += table.stride)
            {
                Widget nameWidget = children[i];
                if (!visible(nameWidget) || nameWidget.getType() != WidgetType.TEXT)
                {
                    continue;
                }
                String name = Names.display(nameWidget.getText());
                if (!Names.isPlayerName(name))
                {
                    continue;
                }
                // Preserve the full native text for sorting, menu actions and player matching.
                reserveNameWidth(nameWidget);
                active.add(nameWidget);
                Rectangle nameBounds = nameWidget.getBounds();
                Rectangle gearBounds = new Rectangle(header.x, nameBounds.y, COLUMN_WIDTH, nameBounds.height);
                Rectangle clippedGear = gearBounds.intersection(clip);
                Rectangle clippedName = nameBounds.intersection(clip);
                if (clippedGear.width > 0 && clippedGear.height > 0)
                {
                    next.add(new ApplicantRow(name, clippedName, clippedGear,
                        GearSnapshot.read(nearby.get(Names.key(name)))));
                }
            }
        }
        // Rebuilds replace widget objects; restore/release the previous generation immediately.
        originalWidths.entrySet().removeIf(entry -> {
            if (active.contains(entry.getKey()))
            {
                return false;
            }
            restore(entry.getKey(), entry.getValue());
            return true;
        });
        rows = Collections.unmodifiableList(next);
        lastTable = table;
    }

    void onScriptPre(int scriptId, Object[] arguments)
    {
        if (scriptId == AUTO_REFRESH_SCRIPT)
        {
            // This timer script runs repeatedly, but only dispatches a refresh at 500 cycles.
            // Its root arguments are [script, universe, pausebuttons, refresh, startClock].
            if (arguments != null && arguments.length >= 5 && arguments[4] instanceof Integer
                && client.getGameCycle() - (Integer) arguments[4] >= AUTO_REFRESH_INTERVAL
                && header != null)
            {
                Widget root = client.getWidget(InterfaceID.ToaPartydetails.CONTENTS);
                if (client.getGameState() == GameState.LOGGED_IN && visible(root))
                {
                    refreshRoot = root;
                    refreshRootBounds = new Rectangle(root.getBounds());
                    refreshStartCycle = client.getGameCycle();
                    rebuilding = false;
                }
            }
        }
        else if (scriptId == INIT_SCRIPT)
        {
            rebuilding = refreshRoot != null && validRefreshContext();
            if (!rebuilding)
            {
                cancelAutomaticRefresh();
            }
        }
    }

    void onScriptPost(int scriptId)
    {
        if (scriptId == COMPLETE_SCRIPT)
        {
            cancelAutomaticRefresh();
            // On immediate reload the script finishes before widget draw coordinates settle.
            // Keep the previous coherent display through this cycle; sample again next cycle.
            if (reloadCycle != client.getGameCycle())
            {
                update();
            }
        }
    }

    void cancelRefresh()
    {
        cancelAutomaticRefresh();
        reloadCycle = -1;
    }

    void noteInterfaceClose()
    {
        if (header != null)
        {
            reloadCycle = client.getGameCycle();
        }
    }

    boolean awaitingReloadLayout()
    {
        return reloadCycle != -1;
    }

    private void cancelAutomaticRefresh()
    {
        refreshRoot = null;
        refreshRootBounds = null;
        rebuilding = false;
    }

    private void updateGearOnly()
    {
        Map<String, Player> nearby = nearbyPlayers();
        List<ApplicantRow> live = new ArrayList<>();
        for (ApplicantRow row : rows)
        {
            live.add(new ApplicantRow(row.name, row.nameBounds, row.gearBounds,
                GearSnapshot.read(nearby.get(Names.key(row.name)))));
        }
        rows = Collections.unmodifiableList(live);
    }

    private void prepareNameWidths(Table table)
    {
        Widget list = client.getWidget(table.list);
        Widget[] children = list == null ? null : list.getChildren();
        if (children != null)
        {
            for (int i = 1; i < children.length; i += table.stride)
            {
                Widget name = children[i];
                if (visible(name) && name.getType() == WidgetType.TEXT && Names.isPlayerName(name.getText()))
                {
                    reserveNameWidth(name);
                }
            }
        }
    }

    private void reserveNameWidth(Widget name)
    {
        int original = originalWidths.computeIfAbsent(name, Widget::getOriginalWidth);
        int width = Math.max(1, original - COLUMN_WIDTH);
        if (name.getOriginalWidth() != width)
        {
            name.setOriginalWidth(width);
            name.revalidate();
        }
    }

    private boolean validRefreshContext()
    {
        int elapsed = client.getGameCycle() - refreshStartCycle;
        Widget root = client.getWidget(InterfaceID.ToaPartydetails.CONTENTS);
        return elapsed >= 0 && elapsed <= MAX_REFRESH_CYCLES
            && root == refreshRoot && visible(root) && root.getBounds().equals(refreshRootBounds);
    }

    private Map<String, Player> nearbyPlayers()
    {
        Map<String, Player> nearby = new HashMap<>();
        for (Player player : client.getPlayers())
        {
            if (player != null && player.getName() != null)
            {
                nearby.put(Names.key(player.getName()), player);
            }
        }
        return nearby;
    }

    private static boolean visible(Widget widget)
    {
        return widget != null && !widget.isHidden();
    }

    private static void restore(Widget widget, int width)
    {
        widget.setOriginalWidth(width);
        widget.revalidate();
    }

    void clear()
    {
        cancelRefresh();
        originalWidths.forEach(ApplicantInterface::restore);
        originalWidths.clear();
        rows = Collections.emptyList();
        header = null;
        lastTable = null;
    }

    List<ApplicantRow> rows()
    {
        return rows;
    }

    Rectangle header()
    {
        return header == null ? null : new Rectangle(header);
    }
}

package com.toa.gear;

import java.awt.Rectangle;

final class ApplicantRow
{
    final String name;
    final Rectangle nameBounds;
    final Rectangle gearBounds;
    final GearSnapshot gear;

    ApplicantRow(String name, Rectangle nameBounds, Rectangle gearBounds, GearSnapshot gear)
    {
        this.name = name;
        this.nameBounds = new Rectangle(nameBounds);
        this.gearBounds = new Rectangle(gearBounds);
        this.gear = gear;
    }
}

package com.toa.gear;

import java.awt.event.MouseEvent;
import javax.inject.Inject;
import net.runelite.client.input.MouseAdapter;

/** Prevent clicks on the hover card from reaching obscured native Accept / Reject buttons. */
final class GearMouseListener extends MouseAdapter
{
    private final ApplicantGearOverlay overlay;
    private boolean captured;

    @Inject
    GearMouseListener(ApplicantGearOverlay overlay)
    {
        this.overlay = overlay;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        captured = overlay.blocks(event.getPoint());
        if (captured)
        {
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent event)
    {
        if (captured || overlay.blocks(event.getPoint()))
        {
            event.consume();
        }
        captured = false;
        return event;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent event)
    {
        if (overlay.blocks(event.getPoint()))
        {
            event.consume();
        }
        return event;
    }
}

package com.toa.gear;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.WeakHashMap;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;

/** Passive equipment card. All coordinates are game-canvas coordinates (also in stretched mode). */
final class GearPanel
{
    static final int WIDTH = 360;
    static final int HEIGHT = 280;
    static final int CELL_SIZE = 40;
    static final int CELL_PITCH = 42;
    static final Color GOLD = new Color(255, 198, 88);
    static final Color MUTED = new Color(174, 166, 146);
    private final ItemManager itemManager;
    private final Map<BufferedImage, Rectangle> spriteContentBounds = new WeakHashMap<>();

    @Inject
    GearPanel(ItemManager itemManager)
    {
        this.itemManager = itemManager;
    }

    static Rectangle place(Rectangle anchor, Dimension canvas)
    {
        int x = anchor.x + anchor.width + 4;
        if (x + WIDTH > canvas.width - 4)
        {
            x = anchor.x - WIDTH - 4;
        }
        x = Math.max(4, Math.min(x, canvas.width - WIDTH - 4));
        int y = Math.max(4, Math.min(anchor.y, canvas.height - HEIGHT - 4));
        return new Rectangle(x, y, WIDTH, HEIGHT);
    }

    void render(Graphics2D graphics, Rectangle bounds, ApplicantRow applicant,
        java.awt.Point mouse)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.translate(bounds.x, bounds.y);
            g.setColor(new Color(10, 9, 6, 100));
            g.fillRect(3, 3, WIDTH, HEIGHT);
            g.setColor(new Color(38, 34, 26, 250));
            g.fillRect(0, 0, WIDTH, HEIGHT);
            g.setColor(new Color(135, 111, 67));
            g.drawRect(0, 0, WIDTH - 1, HEIGHT - 1);
            g.setColor(new Color(77, 66, 45));
            g.drawRect(2, 2, WIDTH - 5, HEIGHT - 5);
            g.setFont(FontManager.getRunescapeBoldFont());
            text(g, applicant.name, 12, 23, GOLD, WIDTH - 24);
            g.setColor(new Color(91, 78, 53));
            g.drawLine(12, 32, WIDTH - 13, 32);

            if (!applicant.gear.available())
            {
                g.setFont(FontManager.getRunescapeFont());
                text(g, applicant.gear.unavailableReason, 14, 66, GOLD, WIDTH - 28);
                text(g, "Stand nearby in the same world to inspect.", 14, 94, MUTED, WIDTH - 28);
                return;
            }

            java.awt.Point localMouse = new java.awt.Point(mouse.x - bounds.x, mouse.y - bounds.y);
            String hovered = null;
            int line = 0;
            for (GearSlot slot : GearSlot.values())
            {
                int itemId = applicant.gear.items.getOrDefault(slot, -1);
                Rectangle cell = new Rectangle(12 + slot.column * CELL_PITCH,
                    41 + slot.row * CELL_PITCH, CELL_SIZE, CELL_SIZE);
                Rectangle row = new Rectangle(148, 41 + line * 23, WIDTH - 160, 23);
                String itemName = itemId < 0 ? "Empty" : itemManager.getItemComposition(itemId).getName();
                boolean hover = cell.contains(localMouse) || row.contains(localMouse);
                if (hover)
                {
                    hovered = slot.label + ": " + itemName;
                }
                g.setColor(hover ? new Color(88, 75, 48) : new Color(49, 43, 31));
                g.fillRect(cell.x, cell.y, cell.width, cell.height);
                g.setColor(hover ? GOLD : new Color(96, 82, 56));
                g.drawRect(cell.x, cell.y, cell.width - 1, cell.height - 1);
                if (itemId >= 0)
                {
                    BufferedImage icon = itemManager.getImage(itemId);
                    if (icon != null)
                    {
                        drawSprite(g, cell, icon);
                    }
                }
                else
                {
                    g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 9));
                    FontMetrics fm = g.getFontMetrics();
                    String emptyLabel = slot.label;
                    g.setColor(MUTED);
                    g.drawString(emptyLabel, cell.x + (cell.width - fm.stringWidth(emptyLabel)) / 2, cell.y + 22);
                }
                g.setFont(FontManager.getRunescapeSmallFont());
                text(g, slot.label, row.x, row.y + 15, MUTED, 46);
                text(g, itemName, row.x + 46, row.y + 15,
                    hover ? GOLD : itemId < 0 ? MUTED : Color.WHITE, row.width - 46);
                line++;
            }
            if (hovered != null)
            {
                g.setFont(FontManager.getRunescapeSmallFont());
                text(g, hovered, 12, 270, GOLD, WIDTH - 24);
            }
        }
        finally
        {
            g.dispose();
        }
    }

    /** Centre the artwork rather than the sprite canvas, which may have unequal transparent margins. */
    void drawSprite(Graphics2D g, Rectangle cell, BufferedImage icon)
    {
        Rectangle source = spriteContentBounds.get(icon);
        if (source == null)
        {
            source = visibleBounds(icon);
            if (source.isEmpty())
            {
                // RuneLite returns blank AsyncBufferedImages before loading. Retry next frame.
                return;
            }
            spriteContentBounds.put(icon, source);
        }
        Rectangle target = spriteBounds(cell, source.width, source.height);
        g.drawImage(icon, target.x, target.y, target.x + target.width, target.y + target.height,
            source.x, source.y, source.x + source.width, source.y + source.height, null);
    }

    static Rectangle visibleBounds(BufferedImage icon)
    {
        int minX = icon.getWidth();
        int minY = icon.getHeight();
        int maxX = -1;
        int maxY = -1;
        for (int y = 0; y < icon.getHeight(); y++)
        {
            for (int x = 0; x < icon.getWidth(); x++)
            {
                if ((icon.getRGB(x, y) >>> 24) != 0)
                {
                    minX = Math.min(minX, x);
                    minY = Math.min(minY, y);
                    maxX = Math.max(maxX, x);
                    maxY = Math.max(maxY, y);
                }
            }
        }
        return maxX < minX ? new Rectangle() : new Rectangle(minX, minY, maxX - minX + 1, maxY - minY + 1);
    }

    /** Artwork keeps native size unless it exceeds the padded interior of the cell. */
    static Rectangle spriteBounds(Rectangle cell, int width, int height)
    {
        int available = Math.min(cell.width, cell.height) - 4;
        double scale = Math.min(1.0, Math.min((double) available / Math.max(1, width),
            (double) available / Math.max(1, height)));
        int drawWidth = Math.max(1, (int) Math.floor(width * scale));
        int drawHeight = Math.max(1, (int) Math.floor(height * scale));
        return new Rectangle(cell.x + (cell.width - drawWidth) / 2,
            cell.y + (cell.height - drawHeight) / 2, drawWidth, drawHeight);
    }

    static void text(Graphics2D g, String value, int x, int y, Color color, int maxWidth)
    {
        FontMetrics fm = g.getFontMetrics();
        String text = value == null ? "Unknown item" : value;
        if (fm.stringWidth(text) > maxWidth)
        {
            while (!text.isEmpty() && fm.stringWidth(text + "...") > maxWidth)
            {
                text = text.substring(0, text.length() - 1);
            }
            text += "...";
        }
        g.setColor(Color.BLACK);
        g.drawString(text, x + 1, y + 1);
        g.setColor(color);
        g.drawString(text, x, y);
    }
}

package com.toa.gear;

import net.runelite.api.kit.KitType;

/** Only nine equipped item slots are part of another player's public appearance. */
enum GearSlot
{
    HEAD("Head", KitType.HEAD, 1, 0),
    CAPE("Cape", KitType.CAPE, 0, 1),
    NECK("Neck", KitType.AMULET, 1, 1),
    WEAPON("Weapon", KitType.WEAPON, 0, 2),
    BODY("Body", KitType.TORSO, 1, 2),
    SHIELD("Shield", KitType.SHIELD, 2, 2),
    LEGS("Legs", KitType.LEGS, 1, 3),
    HANDS("Hands", KitType.HANDS, 0, 4),
    FEET("Feet", KitType.BOOTS, 1, 4);

    final String label;
    final KitType kit;
    final int column;
    final int row;

    GearSlot(String label, KitType kit, int column, int row)
    {
        this.label = label;
        this.kit = kit;
        this.column = column;
        this.row = row;
    }
}

package com.toa.gear;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;

final class GearSnapshot
{
    final Map<GearSlot, Integer> items;
    final String unavailableReason;

    private GearSnapshot(Map<GearSlot, Integer> items, String unavailableReason)
    {
        this.items = Collections.unmodifiableMap(new EnumMap<>(items));
        this.unavailableReason = unavailableReason;
    }

    static GearSnapshot unavailable(String reason)
    {
        return new GearSnapshot(new EnumMap<>(GearSlot.class), reason);
    }

    static GearSnapshot read(Player player)
    {
        if (player == null)
        {
            return unavailable("Out of range / different world");
        }
        PlayerComposition composition = player.getPlayerComposition();
        if (composition == null || composition.getTransformedNpcId() != -1)
        {
            return unavailable("Player appearance unavailable");
        }
        EnumMap<GearSlot, Integer> items = new EnumMap<>(GearSlot.class);
        for (GearSlot slot : GearSlot.values())
        {
            if (slot.kit != null)
            {
                // getEquipmentId already decodes ITEM_OFFSET, which has changed historically.
                // Do not subtract 512/2048 here, or mix in body-part kit IDs.
                items.put(slot, composition.getEquipmentId(slot.kit));
            }
        }
        return new GearSnapshot(items, null);
    }

    boolean available()
    {
        return unavailableReason == null;
    }
}

package com.toa.gear;

import java.util.Locale;
import net.runelite.client.util.Text;

final class Names
{
    private Names() { }

    static String display(String name)
    {
        return name == null ? "" : Text.removeTags(name).replace('\u00a0', ' ').trim();
    }

    static String key(String name)
    {
        return display(name).replace('_', ' ').toLowerCase(Locale.ROOT);
    }

    static boolean isPlayerName(String name)
    {
        // Empty native member seats are rendered as "-", sometimes with colour tags.
        // Real names contain at least one letter or digit; spaces / punctuation alone do not.
        return display(name).chars().anyMatch(Character::isLetterOrDigit);
    }
}

