package com.toa.gear;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.GameState;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "ToA Applicant Gear",
    description = "Inspect nearby members and applicants in any ToA party",
    tags = {"toa", "tombs of amascut", "party", "applicants", "gear"})
public class ToaApplicantGearPlugin extends Plugin
{
    @Inject private ApplicantInterface applicantInterface;
    @Inject private ApplicantGearOverlay overlay;
    @Inject private OverlayManager overlayManager;
    @Inject private ClientThread clientThread;
    @Inject private MouseManager mouseManager;
    @Inject private GearMouseListener mouseListener;
    private volatile boolean running;

    @Provides
    ToaApplicantGearConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(ToaApplicantGearConfig.class);
    }

    @Override
    protected void startUp()
    {
        running = true;
        overlayManager.add(overlay);
        mouseManager.registerMouseListener(mouseListener);
    }

    @Override
    protected void shutDown()
    {
        running = false;
        overlayManager.remove(overlay);
        mouseManager.unregisterMouseListener(mouseListener);
        clientThread.invoke(() -> {
            if (!running)
            {
                applicantInterface.clear();
                overlay.clearHover();
            }
        });
    }

    @Subscribe
    public void onBeforeRender(BeforeRender event)
    {
        if (running)
        {
            applicantInterface.update();
            if (applicantInterface.header() == null)
            {
                overlay.clearHover();
            }
        }
    }

    @Subscribe
    public void onScriptPreFired(ScriptPreFired event)
    {
        if (running)
        {
            applicantInterface.onScriptPre(event.getScriptId(), event.getScriptEvent() == null
                ? null : event.getScriptEvent().getArguments());
        }
    }

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        if (running)
        {
            applicantInterface.onScriptPost(event.getScriptId());
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if ((event.getParam1() >>> 16) == InterfaceID.TOA_PARTYDETAILS)
        {
            // Never bridge an intentional tab/party change or a native accept/reject action.
            applicantInterface.cancelRefresh();
            overlay.clearHover();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            applicantInterface.clear();
            overlay.clearHover();
        }
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        if (event.getGroupId() == InterfaceID.TOA_PARTYDETAILS)
        {
            // This event precedes the actual close and can be followed by reopening the
            // same group in the same cycle, even if its old widgets were unloaded.
            // Validate the live table in BeforeRender instead of clearing hover here.
            applicantInterface.noteInterfaceClose();
        }
    }
}

package com.toa.gearinspector;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Singleton
final class GearInspectorOverlay extends Overlay
{
    private final Client client;
    private final ToaGearInspectorConfig config;
    private final PartyInterface applicants;
    private final GearPanel panel;
    private String hoveredName;
    private volatile Rectangle popupBounds;
    private Rectangle bridge;

    @Inject
    GearInspectorOverlay(Client client, ToaGearInspectorConfig config,
        PartyInterface applicants, GearPanel panel)
    {
        this.client = client;
        this.config = config;
        this.applicants = applicants;
        this.panel = panel;
        setPosition(OverlayPosition.DYNAMIC);
        // Widget callbacks are conditional on native interface drawing. The final buffer pass
        // runs each rendered frame, after native redraws, in both software and GPU clients.
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Rectangle header = applicants.header();
        if (header == null || client.isMenuOpen())
        {
            clearHover();
            return null;
        }
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setColor(GearPanel.GOLD);
            int hx = header.x + header.width / 2;
            int hy = header.y + header.height / 2;
            g.drawPolygon(new int[]{hx - 5, hx + 5, hx + 5, hx, hx - 5},
                new int[]{hy - 5, hy - 5, hy + 2, hy + 6, hy + 2}, 5);
            g.drawLine(hx, hy - 3, hx, hy + 3);
            net.runelite.api.Point point = client.getMouseCanvasPosition();
            java.awt.Point mouse = new java.awt.Point(point.getX(), point.getY());
            PartyRow selected = null;
            // Keep the card open while hovering its items; discard it if that applicant disappears.
            if (hoveredName != null && ((popupBounds != null && popupBounds.contains(mouse))
                || (bridge != null && bridge.contains(mouse))))
            {
                for (PartyRow row : applicants.rows())
                {
                    if (Names.key(row.name).equals(hoveredName))
                    {
                        selected = row;
                        break;
                    }
                }
            }
            for (PartyRow row : applicants.rows())
            {
                boolean rowHovered = row.gearBounds.contains(mouse)
                    || (config.hoverName() && row.nameBounds.contains(mouse));
                // The existing popup is on top of underlying applicant rows.
                if (selected == null && rowHovered)
                {
                    selected = row;
                }
                Rectangle b = row.gearBounds;
                g.setColor(rowHovered ? new Color(119, 94, 48, 170) : new Color(0, 0, 0, 65));
                g.fillRect(b.x + 2, b.y + 2, Math.max(0, b.width - 4), Math.max(0, b.height - 4));
                int x = b.x + b.width / 2;
                int y = b.y + b.height / 2;
                Graphics2D icon = (Graphics2D) g.create();
                try
                {
                    icon.clip(b);
                    icon.setColor(row.gear.available() ? new Color(169, 207, 128) : GearPanel.MUTED);
                    icon.drawOval(x - 6, y - 6, 8, 8);
                    icon.drawLine(x + 1, y + 1, x + 6, y + 6);
                }
                finally
                {
                    icon.dispose();
                }
            }
            if (selected == null)
            {
                clearHover();
                return null;
            }
            hoveredName = Names.key(selected.name);
            Rectangle bounds = GearPanel.place(selected.gearBounds,
                new Dimension(client.getCanvasWidth(), client.getCanvasHeight()));
            popupBounds = bounds;
            bridge = bridge(selected.gearBounds, bounds);
            panel.render(g, bounds, selected, mouse);
            return null;
        }
        finally
        {
            g.dispose();
        }
    }

    static Rectangle bridge(Rectangle anchor, Rectangle popup)
    {
        int left = Math.min(anchor.x + anchor.width, popup.x + popup.width);
        int right = Math.max(anchor.x, popup.x);
        int top = Math.max(anchor.y, popup.y);
        int bottom = Math.min(anchor.y + anchor.height, popup.y + popup.height);
        return new Rectangle(left, top, Math.max(0, right - left), Math.max(0, bottom - top));
    }

    boolean blocks(java.awt.Point point)
    {
        Rectangle bounds = popupBounds;
        return bounds != null && bounds.contains(point);
    }

    void clearHover()
    {
        hoveredName = null;
        popupBounds = null;
        bridge = null;
    }
}

package com.toa.gearinspector;

import java.awt.event.MouseEvent;
import javax.inject.Inject;
import net.runelite.client.input.MouseAdapter;

/** Prevent clicks on the hover card from reaching obscured native Accept / Reject buttons. */
final class GearMouseListener extends MouseAdapter
{
    private final GearInspectorOverlay overlay;
    private boolean captured;

    @Inject
    GearMouseListener(GearInspectorOverlay overlay)
    {
        this.overlay = overlay;
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        captured = overlay.blocks(event.getPoint());
        if (captured)
        {
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent event)
    {
        if (captured || overlay.blocks(event.getPoint()))
        {
            event.consume();
        }
        captured = false;
        return event;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent event)
    {
        if (overlay.blocks(event.getPoint()))
        {
            event.consume();
        }
        return event;
    }
}

package com.toa.gearinspector;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.WeakHashMap;
import javax.inject.Inject;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;

/** Passive equipment card. All coordinates are game-canvas coordinates (also in stretched mode). */
final class GearPanel
{
    static final int WIDTH = 360;
    static final int HEIGHT = 280;
    static final int CELL_SIZE = 40;
    static final int CELL_PITCH = 42;
    static final Color GOLD = new Color(255, 198, 88);
    static final Color MUTED = new Color(174, 166, 146);
    private final ItemManager itemManager;
    private final Map<BufferedImage, Rectangle> spriteContentBounds = new WeakHashMap<>();

    @Inject
    GearPanel(ItemManager itemManager)
    {
        this.itemManager = itemManager;
    }

    static Rectangle place(Rectangle anchor, Dimension canvas)
    {
        int x = anchor.x + anchor.width + 4;
        if (x + WIDTH > canvas.width - 4)
        {
            x = anchor.x - WIDTH - 4;
        }
        x = Math.max(4, Math.min(x, canvas.width - WIDTH - 4));
        int y = Math.max(4, Math.min(anchor.y, canvas.height - HEIGHT - 4));
        return new Rectangle(x, y, WIDTH, HEIGHT);
    }

    void render(Graphics2D graphics, Rectangle bounds, PartyRow applicant,
        java.awt.Point mouse)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.translate(bounds.x, bounds.y);
            g.setColor(new Color(10, 9, 6, 100));
            g.fillRect(3, 3, WIDTH, HEIGHT);
            g.setColor(new Color(38, 34, 26, 250));
            g.fillRect(0, 0, WIDTH, HEIGHT);
            g.setColor(new Color(135, 111, 67));
            g.drawRect(0, 0, WIDTH - 1, HEIGHT - 1);
            g.setColor(new Color(77, 66, 45));
            g.drawRect(2, 2, WIDTH - 5, HEIGHT - 5);
            g.setFont(FontManager.getRunescapeBoldFont());
            text(g, applicant.name, 12, 23, GOLD, WIDTH - 24);
            g.setColor(new Color(91, 78, 53));
            g.drawLine(12, 32, WIDTH - 13, 32);

            if (!applicant.gear.available())
            {
                g.setFont(FontManager.getRunescapeFont());
                text(g, applicant.gear.unavailableReason, 14, 66, GOLD, WIDTH - 28);
                text(g, "Stand nearby in the same world to inspect.", 14, 94, MUTED, WIDTH - 28);
                return;
            }

            java.awt.Point localMouse = new java.awt.Point(mouse.x - bounds.x, mouse.y - bounds.y);
            String hovered = null;
            int line = 0;
            for (GearSlot slot : GearSlot.values())
            {
                int itemId = applicant.gear.items.getOrDefault(slot, -1);
                Rectangle cell = new Rectangle(12 + slot.column * CELL_PITCH,
                    41 + slot.row * CELL_PITCH, CELL_SIZE, CELL_SIZE);
                Rectangle row = new Rectangle(148, 41 + line * 23, WIDTH - 160, 23);
                String itemName = itemId < 0 ? "Empty" : itemManager.getItemComposition(itemId).getName();
                boolean hover = cell.contains(localMouse) || row.contains(localMouse);
                if (hover)
                {
                    hovered = slot.label + ": " + itemName;
                }
                g.setColor(hover ? new Color(88, 75, 48) : new Color(49, 43, 31));
                g.fillRect(cell.x, cell.y, cell.width, cell.height);
                g.setColor(hover ? GOLD : new Color(96, 82, 56));
                g.drawRect(cell.x, cell.y, cell.width - 1, cell.height - 1);
                if (itemId >= 0)
                {
                    BufferedImage icon = itemManager.getImage(itemId);
                    if (icon != null)
                    {
                        drawSprite(g, cell, icon);
                    }
                }
                else
                {
                    g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 9));
                    FontMetrics fm = g.getFontMetrics();
                    String emptyLabel = slot.label;
                    g.setColor(MUTED);
                    g.drawString(emptyLabel, cell.x + (cell.width - fm.stringWidth(emptyLabel)) / 2, cell.y + 22);
                }
                g.setFont(FontManager.getRunescapeSmallFont());
                text(g, slot.label, row.x, row.y + 15, MUTED, 46);
                text(g, itemName, row.x + 46, row.y + 15,
                    hover ? GOLD : itemId < 0 ? MUTED : Color.WHITE, row.width - 46);
                line++;
            }
            if (hovered != null)
            {
                g.setFont(FontManager.getRunescapeSmallFont());
                text(g, hovered, 12, 270, GOLD, WIDTH - 24);
            }
        }
        finally
        {
            g.dispose();
        }
    }

    /** Centre the artwork rather than the sprite canvas, which may have unequal transparent margins. */
    void drawSprite(Graphics2D g, Rectangle cell, BufferedImage icon)
    {
        Rectangle source = spriteContentBounds.get(icon);
        if (source == null)
        {
            source = visibleBounds(icon);
            if (source.isEmpty())
            {
                // RuneLite returns blank AsyncBufferedImages before loading. Retry next frame.
                return;
            }
            spriteContentBounds.put(icon, source);
        }
        Rectangle target = spriteBounds(cell, source.width, source.height);
        g.drawImage(icon, target.x, target.y, target.x + target.width, target.y + target.height,
            source.x, source.y, source.x + source.width, source.y + source.height, null);
    }

    static Rectangle visibleBounds(BufferedImage icon)
    {
        int minX = icon.getWidth();
        int minY = icon.getHeight();
        int maxX = -1;
        int maxY = -1;
        for (int y = 0; y < icon.getHeight(); y++)
        {
            for (int x = 0; x < icon.getWidth(); x++)
            {
                if ((icon.getRGB(x, y) >>> 24) != 0)
                {
                    minX = Math.min(minX, x);
                    minY = Math.min(minY, y);
                    maxX = Math.max(maxX, x);
                    maxY = Math.max(maxY, y);
                }
            }
        }
        return maxX < minX ? new Rectangle() : new Rectangle(minX, minY, maxX - minX + 1, maxY - minY + 1);
    }

    /** Artwork keeps native size unless it exceeds the padded interior of the cell. */
    static Rectangle spriteBounds(Rectangle cell, int width, int height)
    {
        int available = Math.min(cell.width, cell.height) - 4;
        double scale = Math.min(1.0, Math.min((double) available / Math.max(1, width),
            (double) available / Math.max(1, height)));
        int drawWidth = Math.max(1, (int) Math.floor(width * scale));
        int drawHeight = Math.max(1, (int) Math.floor(height * scale));
        return new Rectangle(cell.x + (cell.width - drawWidth) / 2,
            cell.y + (cell.height - drawHeight) / 2, drawWidth, drawHeight);
    }

    static void text(Graphics2D g, String value, int x, int y, Color color, int maxWidth)
    {
        FontMetrics fm = g.getFontMetrics();
        String text = value == null ? "Unknown item" : value;
        if (fm.stringWidth(text) > maxWidth)
        {
            while (!text.isEmpty() && fm.stringWidth(text + "...") > maxWidth)
            {
                text = text.substring(0, text.length() - 1);
            }
            text += "...";
        }
        g.setColor(Color.BLACK);
        g.drawString(text, x + 1, y + 1);
        g.setColor(color);
        g.drawString(text, x, y);
    }
}

package com.toa.gearinspector;

import net.runelite.api.kit.KitType;

/** Only nine equipped item slots are part of another player's public appearance. */
enum GearSlot
{
    HEAD("Head", KitType.HEAD, 1, 0),
    CAPE("Cape", KitType.CAPE, 0, 1),
    NECK("Neck", KitType.AMULET, 1, 1),
    WEAPON("Weapon", KitType.WEAPON, 0, 2),
    BODY("Body", KitType.TORSO, 1, 2),
    SHIELD("Shield", KitType.SHIELD, 2, 2),
    LEGS("Legs", KitType.LEGS, 1, 3),
    HANDS("Hands", KitType.HANDS, 0, 4),
    FEET("Feet", KitType.BOOTS, 1, 4);

    final String label;
    final KitType kit;
    final int column;
    final int row;

    GearSlot(String label, KitType kit, int column, int row)
    {
        this.label = label;
        this.kit = kit;
        this.column = column;
        this.row = row;
    }
}

